using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using Object=UnityEngine.Object;
namespace CoastalFactory.Editor {
public static class QuayAssetBuilder {
 const string Root="Assets/_Anseong/Art/Environment/Assets/Quay";
 static readonly List<GameObject> pieces=new List<GameObject>();
 static void Folder(string p){if(AssetDatabase.IsValidFolder(p))return;var parent=Path.GetDirectoryName(p).Replace('\\','/');Folder(parent);AssetDatabase.CreateFolder(parent,Path.GetFileName(p));}
 static Material Mat(string name,Color color){var existing=AssetDatabase.LoadAssetAtPath<Material>(Root+"/"+name+".mat");if(existing)return existing;var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=color;m.SetFloat("_Smoothness",.08f);m.enableInstancing=true;AssetDatabase.CreateAsset(m,Root+"/"+name+".mat");return m;}
 static void Box(Transform parent,string name,Vector3 pos,Vector3 size,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;Object.DestroyImmediate(g.GetComponent<Collider>());pieces.Add(g);}
 static Mesh Bake(Transform root,Material[] materials){var temps=new List<Mesh>();var final=new CombineInstance[materials.Length];for(int i=0;i<materials.Length;i++){var list=new List<CombineInstance>();foreach(var g in pieces)if(g.GetComponent<Renderer>().sharedMaterial==materials[i])list.Add(new CombineInstance{mesh=g.GetComponent<MeshFilter>().sharedMesh,transform=root.worldToLocalMatrix*g.transform.localToWorldMatrix});var part=new Mesh();part.CombineMeshes(list.ToArray(),true,true);temps.Add(part);final[i]=new CombineInstance{mesh=part,transform=Matrix4x4.identity};}var mesh=new Mesh{name="Quay_20m"};mesh.CombineMeshes(final,false,true);mesh.RecalculateBounds();foreach(var m in temps)Object.DestroyImmediate(m);return mesh;}
 [MenuItem("Anseong/Art/Build Quay Module")]
 public static void Build(){Folder(Root);var concrete=Mat("Concrete",new Color(.44f,.45f,.42f));var cap=Mat("CopingConcrete",new Color(.55f,.55f,.50f));var wet=Mat("WetConcrete",new Color(.23f,.28f,.24f));var joint=Mat("Joints",new Color(.19f,.22f,.21f));var yellow=Mat("SafetyYellow",new Color(.75f,.53f,.12f));var sea=Mat("SeaPreview",new Color(.07f,.28f,.36f));pieces.Clear();var root=new GameObject("Quay_20m");var r=root.transform;
  // Pivot: seaward edge at ground level. Land -X, water +X, length along Z.
  Box(r,"RetainingWall",new Vector3(-.6f,-3,0),new Vector3(1.2f,6,20),concrete);Box(r,"WetBand",new Vector3(.015f,-4.5f,0),new Vector3(.03f,3,20),wet);Box(r,"Apron",new Vector3(-5,-.2f,0),new Vector3(10,.4f,20),concrete);Box(r,"Coping",new Vector3(-.45f,-.12f,0),new Vector3(.9f,.24f,20),cap);
  // Shallow construction joints and stagger-free repeated markings.
  for(int i=0;i<4;i++){float z=-7.5f+i*5;Box(r,"WallJoint",new Vector3(.02f,-1.5f,z),new Vector3(.025f,3,.035f),joint);Box(r,"DeckJoint",new Vector3(-5,.003f,z),new Vector3(9,.006f,.025f),joint);}
  for(int i=0;i<10;i++)Box(r,"EdgeWarning",new Vector3(-1.15f,.008f,-9+i*2),new Vector3(.16f,.016f,1.15f),yellow);
  var mesh=Bake(r,new[]{concrete,cap,wet,joint,yellow});string path=Root+"/Quay_20m.asset";var previous=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(previous){EditorUtility.CopySerialized(mesh,previous);Object.DestroyImmediate(mesh);mesh=previous;}else AssetDatabase.CreateAsset(mesh,path);foreach(var g in pieces)Object.DestroyImmediate(g);pieces.Clear();root.AddComponent<MeshFilter>().sharedMesh=mesh;root.AddComponent<MeshRenderer>().sharedMaterials=new[]{concrete,cap,wet,joint,yellow};var wall=root.AddComponent<BoxCollider>();wall.center=new Vector3(-.6f,-3,0);wall.size=new Vector3(1.2f,6,20);var deck=root.AddComponent<BoxCollider>();deck.center=new Vector3(-5,-.2f,0);deck.size=new Vector3(10,.4f,20);var prefab=PrefabUtility.SaveAsPrefabAsset(root,Root+"/Quay_20m.prefab");Object.DestroyImmediate(root);
  Folder("Assets/_Anseong/Scenes/Sandbox");EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects,NewSceneMode.Single);for(int i=0;i<3;i++){var part=(GameObject)PrefabUtility.InstantiatePrefab(prefab);part.transform.position=new Vector3(0,0,(i-1)*20);}var water=GameObject.CreatePrimitive(PrimitiveType.Cube);water.name="Sea_Y_Minus3_Preview";water.transform.position=new Vector3(35,-3.05f,0);water.transform.localScale=new Vector3(70,.1f,100);water.GetComponent<Renderer>().sharedMaterial=sea;Object.DestroyImmediate(water.GetComponent<Collider>());var camera=Camera.main;camera.transform.position=new Vector3(36,25,-41);camera.transform.LookAt(new Vector3(-2,-1,0));camera.fieldOfView=47;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.32f,.43f,.52f);var sun=Object.FindFirstObjectByType<Light>();sun.intensity=2;sun.transform.rotation=Quaternion.Euler(45,-35,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.65f,.68f,.72f);EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/_Anseong/Scenes/Sandbox/Sandbox_Quay.unity");AssetDatabase.SaveAssets();int tris=mesh.triangles.Length/3;if(tris>400||Mathf.Abs(mesh.bounds.size.z-20)>.001f||Mathf.Abs(mesh.bounds.max.y-.016f)>.02f||prefab.GetComponentsInChildren<Rigidbody>().Length!=0)throw new Exception("Quay validation failed");Capture(camera);Debug.Log("QUAY_TEST_PASS triangles="+tris+" moduleLength=20 deckWidth=10 deckY=0 bottomY=-6 colliders=2 rigidbodies=0");
 }
 static void Capture(Camera camera){var rt=new RenderTexture(1200,850,24);var old=RenderTexture.active;camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var image=new Texture2D(1200,850,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1200,850),0,0);image.Apply();File.WriteAllBytes("C:/Users/Admin/Documents/ChatGPT/안성제철/output/Quay_Preview.png",image.EncodeToPNG());camera.targetTexture=null;RenderTexture.active=old;Object.DestroyImmediate(image);Object.DestroyImmediate(rt);}
}
